question.template:
"""Grader for the UniCV "write the expression" prototype (unicv_python3_expression).

Each item of the question is a statement in words (e.g. "a, b and c can be the
sides of a triangle") and the variables the student may use. The student writes
one Python expression per item. The teacher's correct expressions are in the
question's Answer (never sent to the student's page).

An expression is correct when, for every combination of values tested, it gives
the same result as the teacher's expression. The values tested include all the
combinations of small domains, the boundary values around the constants of the
teacher's expression (17, 18 and 19 for ">= 18"), equal values, and random
values. When an expression is wrong, the feedback shows a counterexample.

Global extra format, one block per item:
    ## The statement shown to the student (`code` between backquotes)
    vars: a, b, c in 0..20           integers from 0 to 20
    vars: x in 0.0..10.0             real numbers
    vars: name in "Ana", "Rui", ""   a list of values
    vars: done in bool               True and False
    allow: len, abs                  functions that may be called (default: none)
    forbid: not, ==                  operators or functions that may not be used
    require: chain                   operators that must be used

The answers are {"exprs": ["[expr1, expr2, ...]"]}. The result of each item is
written in the feedback as <span class="unicv-ex-item" data-item="N" data-ok="1|0">.
"""
import ast
import html
import itertools
import json
import math
import random
import re
import signal

STUDENT_ANSWER = """{{ STUDENT_ANSWER | e('py') }}"""
QUESTION_ANSWER = """{{ QUESTION.answer | e('py') }}"""
GLOBAL_EXTRA = """{{ QUESTION.globalextra | e('py') }}"""
ALL_OR_NOTHING = "{{ QUESTION.allornothing }}" == "1"
IS_PRECHECK = "{{ IS_PRECHECK }}" == "1"

try:
    PARAMS = json.loads("""{{ QUESTION.parameters | json_encode | e('py') }}""")
except ValueError:
    PARAMS = {}
if not isinstance(PARAMS, dict):  # Twig encodes an empty set of parameters as []
    PARAMS = {}

SHOW_COUNTEREXAMPLE = PARAMS.get('showcounterexample', True)
MAX_CASES = int(PARAMS.get('maxcases', 20000))
TIMEOUT = float(PARAMS.get('timeout', 10))

# Names of operators that can be used in forbid: and require:
OPERATORS = {
    'and': ast.And, 'or': ast.Or, 'not': ast.Not,
    '==': ast.Eq, '!=': ast.NotEq, '<': ast.Lt, '<=': ast.LtE, '>': ast.Gt, '>=': ast.GtE,
    'in': ast.In, 'not in': ast.NotIn, 'is': ast.Is,
    '+': ast.Add, '-': ast.Sub, '*': ast.Mult, '/': ast.Div, '//': ast.FloorDiv, '%': ast.Mod, '**': ast.Pow,
    'if': ast.IfExp,
}
SAFE_FUNCTIONS = {'abs': abs, 'len': len, 'min': min, 'max': max, 'round': round, 'int': int,
                  'float': float, 'str': str, 'bool': bool, 'sum': sum, 'sorted': sorted}


# ---------------------------------------------------------------------------
# Reading the question
# ---------------------------------------------------------------------------

def expand(text):
    def value(match):
        name = match.group(1)
        if name in PARAMS:
            v = PARAMS[name]
            return v if isinstance(v, str) else json.dumps(v)
        return match.group(0)
    return re.sub(r'\{\{\s*([A-Za-z_]\w*)\s*\}\}', value, text)


def parse_domain(text):
    """The kind and the values of a domain: ('int', lo, hi), ('float', lo, hi), ('list', values) or ('bool',)."""
    text = text.strip()
    if text.lower() == 'bool':
        return ('list', [True, False])
    match = re.fullmatch(r'(-?\d+(?:\.\d+)?)\s*\.\.\s*(-?\d+(?:\.\d+)?)', text)
    if match:
        lo, hi = match.group(1), match.group(2)
        if '.' in lo or '.' in hi:
            return ('float', float(lo), float(hi))
        return ('int', int(lo), int(hi))
    values = ast.literal_eval('[' + text + ']')
    return ('list', list(values))


def parse(text):
    """The list of items: {statement, vars: [(name, domain)], allow, forbid, require}."""
    items = []
    current = None
    for line in expand(text).replace('\r\n', '\n').split('\n'):
        stripped = line.strip()
        if stripped.startswith('##'):
            current = {'statement': stripped[2:].strip(), 'vars': [], 'allow': [], 'forbid': [], 'require': []}
            items.append(current)
            continue
        if current is None or not stripped:
            continue
        match = re.match(r'^(vars|allow|forbid|require)\s*:\s*(.*)$', stripped, re.I)
        if not match:
            current['statement'] += ' ' + stripped
            continue
        key, rest = match.group(1).lower(), match.group(2)
        if key == 'vars':
            names, _, domain = rest.partition(' in ')
            parsed = parse_domain(domain)
            for name in names.split(','):
                if name.strip():
                    current['vars'].append((name.strip(), parsed))
        else:
            current[key].extend(x.strip() for x in rest.split(',') if x.strip())
    return items


def read_exprs(answer):
    try:
        data = json.loads(answer)
        raw = data.get('exprs', [''])
        raw = raw[0] if isinstance(raw, list) else raw
        exprs = json.loads(raw) if raw else []
        return [str(e) for e in exprs]
    except (ValueError, TypeError, AttributeError):
        return []


# ---------------------------------------------------------------------------
# Checking an expression before running it
# ---------------------------------------------------------------------------

def check(expr, item):
    """(compiled code, None) or (None, message)."""
    text = expr.strip()
    if not text:
        return None, 'Write an expression.'
    if '\n' in text:
        return None, 'The expression must be on one line.'
    try:
        tree = ast.parse(text, mode='eval')
    except SyntaxError as err:
        return None, f'Syntax error: {err.msg}.'
    names = {name for name, _ in item['vars']}
    allowed = set(item['allow'])
    for node in ast.walk(tree):
        if isinstance(node, ast.Name):
            if node.id in names or node.id in ('True', 'False', 'None'):
                continue
            if node.id in allowed and node.id in SAFE_FUNCTIONS:
                continue
            if node.id in SAFE_FUNCTIONS:
                return None, f'You may not use the function {node.id}() in this expression.'
            return None, f'Unknown name {node.id}: the variables are {", ".join(sorted(names))}.'
        if isinstance(node, ast.Attribute) and node.attr.startswith('_'):
            return None, 'Names starting with _ may not be used.'
        if isinstance(node, (ast.Lambda, ast.NamedExpr, ast.ListComp, ast.SetComp, ast.DictComp, ast.GeneratorExp)):
            return None, 'Write a simple expression (no lambda, := or comprehensions).'
        if isinstance(node, ast.Call):
            func = node.func
            if isinstance(func, ast.Name) and func.id not in allowed:
                return None, f'You may not call {func.id}() in this expression.'
            if isinstance(func, ast.Attribute) and 'methods' not in allowed:
                return None, f'You may not call methods such as .{func.attr}() in this expression.'
    used = used_operators(tree)
    for op in item['forbid']:
        if op in used:
            return None, f'You may not use {op} in this expression.'
    for op in item['require']:
        if op not in used:
            what = 'a chained comparison (such as 0 < x < 10)' if op == 'chain' else op
            return None, f'Your expression must use {what}.'
    return compile(tree, 'expression', 'eval'), None


def used_operators(tree):
    used = set()
    for node in ast.walk(tree):
        for name, cls in OPERATORS.items():
            if isinstance(node, cls):
                used.add(name)
        if isinstance(node, ast.Compare) and len(node.ops) > 1:
            used.add('chain')
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
            used.add(node.func.id)
    return used


# ---------------------------------------------------------------------------
# The values tested
# ---------------------------------------------------------------------------

def constants(tree):
    found = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and not isinstance(node.value, bool):
            found.add(node.value)
    return found


def candidates(domain, consts, rng):
    kind = domain[0]
    if kind == 'list':
        return list(domain[1])
    lo, hi = domain[1], domain[2]
    if kind == 'int':
        if hi - lo <= 40:
            return list(range(lo, hi + 1))
        values = {lo, lo + 1, hi - 1, hi, 0, 1, -1, 2}
        for c in consts:
            for d in (-1, 0, 1):
                values.add(int(c) + d)
        values.update(rng.randint(lo, hi) for _ in range(20))
        for c in consts:   # Multiples of the constants (divisibility: ano % 400 == 0).
            c = abs(int(c))
            if c >= 2:
                first, last = -(-lo // c), hi // c
                if first <= last:
                    values.update(c * rng.randint(first, last) for _ in range(4))
                    values.update({c * first, c * last})
        return sorted(v for v in values if lo <= v <= hi)
    values = {lo, hi, (lo + hi) / 2, 0.0, 0.5, 1.0}
    for c in consts:
        for d in (-0.5, -0.01, 0, 0.01, 0.5):
            values.add(float(c) + d)
    values.update(round(rng.uniform(lo, hi), 2) for _ in range(12))
    return sorted(v for v in values if lo <= v <= hi)


def cases(item, ref_tree):
    rng = random.Random(12345)
    names = [name for name, _ in item['vars']]
    consts = constants(ref_tree)
    pools = [candidates(domain, consts, rng) for _, domain in item['vars']]
    # Use every value of the integer ranges when the number of combinations allows it.
    full = [list(range(d[1], d[2] + 1)) if d[0] == 'int' else pool for (_, d), pool in zip(item['vars'], pools)]
    total_full = 1
    for pool in full:
        total_full *= max(1, len(pool))
    if total_full <= MAX_CASES:
        pools = full
    total = 1
    for pool in pools:
        total *= max(1, len(pool))
    if total <= MAX_CASES:
        combos = list(itertools.product(*pools))
    else:
        combos = [tuple(rng.choice(pool) for pool in pools) for _ in range(MAX_CASES)]
        # Equal values matter (equilateral, isosceles...): add combinations with repeated values.
        numeric = [k for k, (_, d) in enumerate(item['vars']) if d[0] in ('int', 'float')]
        for k1, k2 in itertools.combinations(numeric, 2):
            for v in pools[k1]:
                if v in pools[k2]:
                    for _ in range(3):
                        combo = [rng.choice(pool) for pool in pools]
                        combo[k1] = combo[k2] = v
                        combos.append(tuple(combo))
        for v in pools[numeric[0]] if numeric else []:
            combo = [rng.choice(pool) for pool in pools]
            for k in numeric:
                if v in pools[k]:
                    combo[k] = v
            combos.append(tuple(combo))
    return names, combos


# ---------------------------------------------------------------------------
# Comparing
# ---------------------------------------------------------------------------

class TimeLimit(Exception):
    pass


def on_alarm(signum, frame):
    raise TimeLimit()


def evaluate(code, scope):
    try:
        return eval(code, scope), ''
    except TimeLimit:
        raise
    except Exception as exc:
        return None, type(exc).__name__


def same(a, b):
    if isinstance(a, bool) or isinstance(b, bool):
        return type(a) is type(b) and a == b
    if isinstance(a, float) or isinstance(b, float):
        try:
            return math.isclose(a, b, rel_tol=1e-9, abs_tol=1e-9)
        except TypeError:
            return False
    return type(a) is type(b) and a == b


def show_values(names, combo):
    return ', '.join(f'{n} = {v!r}' for n, v in zip(names, combo))


def compare(ref_code, ref_tree, code, item):
    """(ok, message, number of cases tested)."""
    names, combos = cases(item, ref_tree)
    builtins = {name: SAFE_FUNCTIONS[name] for name in item['allow'] if name in SAFE_FUNCTIONS}
    tested = 0
    for combo in combos:
        scope = {'__builtins__': builtins}
        scope.update(zip(names, combo))
        expected, ref_error = evaluate(ref_code, dict(scope))
        if ref_error:
            continue   # Values for which the teacher's expression is not defined.
        got, error = evaluate(code, dict(scope))
        tested += 1
        where = show_values(names, combo)
        if error:
            return False, f'With {where}, your expression gives an error ({error}).', tested
        if isinstance(expected, bool) and not isinstance(got, bool):
            return False, f'Your expression must give True or False, but with {where} it gives {got!r}.', tested
        if not same(got, expected):
            return False, f'With {where}, your expression gives {got!r}, but it should give {expected!r}.', tested
    return True, '', tested


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

def mark(i, ok, text):
    return (f'<span class="unicv-ex-item" data-item="{i}" data-ok="{1 if ok else 0}" style="display:none">'
            f'{html.escape(text)}</span>')


def main():
    items = parse(GLOBAL_EXTRA)
    outcome = {'fraction': 0.0}
    if not items:
        outcome['prologuehtml'] = "<div class='coderunner-test-results bad'><h3>This question has no items</h3><p>Please tell your teacher.</p></div>"
        return outcome
    refs = [expand(r) for r in read_exprs(QUESTION_ANSWER)]
    exprs = read_exprs(STUDENT_ANSWER)

    problems = []
    ref_codes = []
    for k, item in enumerate(items):
        ref = refs[k] if k < len(refs) else ''
        code, message = check(ref, item) if ref.strip() else (None, 'missing')
        if code is None:
            problems.append(f'item {k + 1}: the correct expression in the Answer is {"missing" if message == "missing" else "not valid (" + message + ")"}')
        ref_codes.append((code, ast.parse(ref, mode='eval') if code else None))
    if problems:
        outcome['prologuehtml'] = ("<div class='coderunner-test-results bad'><h3>This question has a problem</h3><ul>" +
                                   ''.join(f'<li>{html.escape(p)}</li>' for p in problems) +
                                   '</ul><p>Please tell your teacher.</p></div>')
        return outcome

    if IS_PRECHECK:
        found = []
        for k, item in enumerate(items):
            expr = exprs[k] if k < len(exprs) else ''
            if expr.strip():
                message = check(expr, item)[1]
                if message:
                    found.append(f'Expression {k + 1}: {message}')
        outcome['fraction'] = 0.0 if found else 1.0
        outcome['prologuehtml'] = ("<div class='coderunner-test-results bad'><h3>Precheck</h3><ul>" +
                                   ''.join(f'<li>{html.escape(f)}</li>' for f in found) + '</ul></div>' if found else
                                   "<p class='precheckresult'>Precheck: your expressions are well written (they have not been tested yet).</p>")
        return outcome

    signal.signal(signal.SIGALRM, on_alarm)
    signal.setitimer(signal.ITIMER_REAL, TIMEOUT)
    results = []
    try:
        for k, item in enumerate(items):
            expr = exprs[k] if k < len(exprs) else ''
            code, message = check(expr, item)
            if code is None:
                results.append((False, message))
                continue
            ok, message, tested = compare(ref_codes[k][0], ref_codes[k][1], code, item)
            if not ok and not SHOW_COUNTEREXAMPLE:
                message = 'Not correct: for some values your expression gives a wrong result.'
            results.append((ok, message or f'Correct (checked with {tested} combinations of values).'))
    except TimeLimit:
        results += [(False, 'Testing took too long.')] * (len(items) - len(results))
    finally:
        signal.setitimer(signal.ITIMER_REAL, 0)

    right = sum(1 for ok, _ in results if ok)
    total = len(items)
    outcome['fraction'] = (1.0 if right == total else 0.0) if ALL_OR_NOTHING else right / total
    good = right == total
    style = 'style="border:1px solid #c4cdd5;padding:4px 8px;vertical-align:top"'
    parts = [f"<div class='coderunner-test-results {'good' if good else 'bad'}'><h3>"
             f"{'All your expressions are correct.' if good else f'{right} of your {total} expressions {"is" if right == 1 else "are"} correct.'}</h3></div>",
             f'<table style="border-collapse:collapse;margin-top:8px"><tr><th {style}>#</th><th {style}>Your expression</th><th {style}></th></tr>']
    for k, (ok, message) in enumerate(results):
        expr = exprs[k] if k < len(exprs) else ''
        sign = '<span style="color:#2f7d32;font-weight:700">✓</span>' if ok else \
            f'<span style="color:#a51d2a;font-weight:700">✗</span> {html.escape(message)}'
        parts.append(f'<tr><td {style}>{k + 1}</td><td {style}><code>{html.escape(expr)}</code></td><td {style}>{sign}</td></tr>')
    parts.append('</table>')
    parts.extend(mark(k, ok, message) for k, (ok, message) in enumerate(results))
    outcome['prologuehtml'] = ''.join(parts)
    return outcome


print(json.dumps(main()))
